/* eslint-disable */
import { PluginContainerData } from './common.js';
import { Animation } from './animation.js';

import {
  DividerData_LineStyle,
  DividerData_Width,
  DividerData_Alignment,
  DividerData_Styles_LineCap,
} from './plugin_divider.enums.js';

export interface DividerData {
  /** Styling for the divider's container. */
  containerData?: PluginContainerData;
  /** Divider line style. */
  lineStyle: DividerData_LineStyle;
  /** Divider width. */
  width: DividerData_Width;
  /** Divider alignment. */
  alignment: DividerData_Alignment;
  /** Visual styling for the divider lines. */
  styles?: DividerData_Styles;
  /** Node animation. */
  animation?: Animation;
}

export function dividerData_LineStyleFromJSON(
  object: any
): DividerData_LineStyle {
  switch (object) {
    case 0:
    case "SINGLE":
      return DividerData_LineStyle.SINGLE;
    case 1:
    case "DOUBLE":
      return DividerData_LineStyle.DOUBLE;
    case 2:
    case "DASHED":
      return DividerData_LineStyle.DASHED;
    case 3:
    case "DOTTED":
      return DividerData_LineStyle.DOTTED;
    case -1:
    case "UNRECOGNIZED":
    default:
      return DividerData_LineStyle.UNRECOGNIZED;
  }
}

export function dividerData_LineStyleToJSON(
  object: DividerData_LineStyle
): string {
  switch (object) {
    case DividerData_LineStyle.SINGLE:
      return "SINGLE";
    case DividerData_LineStyle.DOUBLE:
      return "DOUBLE";
    case DividerData_LineStyle.DASHED:
      return "DASHED";
    case DividerData_LineStyle.DOTTED:
      return "DOTTED";
    default:
      return "UNKNOWN";
  }
}

export function dividerData_WidthFromJSON(object: any): DividerData_Width {
  switch (object) {
    case 0:
    case "LARGE":
      return DividerData_Width.LARGE;
    case 1:
    case "MEDIUM":
      return DividerData_Width.MEDIUM;
    case 2:
    case "SMALL":
      return DividerData_Width.SMALL;
    case -1:
    case "UNRECOGNIZED":
    default:
      return DividerData_Width.UNRECOGNIZED;
  }
}

export function dividerData_WidthToJSON(object: DividerData_Width): string {
  switch (object) {
    case DividerData_Width.LARGE:
      return "LARGE";
    case DividerData_Width.MEDIUM:
      return "MEDIUM";
    case DividerData_Width.SMALL:
      return "SMALL";
    default:
      return "UNKNOWN";
  }
}

export function dividerData_AlignmentFromJSON(
  object: any
): DividerData_Alignment {
  switch (object) {
    case 0:
    case "CENTER":
      return DividerData_Alignment.CENTER;
    case 1:
    case "LEFT":
      return DividerData_Alignment.LEFT;
    case 2:
    case "RIGHT":
      return DividerData_Alignment.RIGHT;
    case -1:
    case "UNRECOGNIZED":
    default:
      return DividerData_Alignment.UNRECOGNIZED;
  }
}

export function dividerData_AlignmentToJSON(
  object: DividerData_Alignment
): string {
  switch (object) {
    case DividerData_Alignment.CENTER:
      return "CENTER";
    case DividerData_Alignment.LEFT:
      return "LEFT";
    case DividerData_Alignment.RIGHT:
      return "RIGHT";
    default:
      return "UNKNOWN";
  }
}

export interface DividerData_Styles {
  /** Divider color as a hexadecimal value. An alpha channel controls opacity. */
  color?: string;
  /** Divider line ending shape. */
  lineCap: DividerData_Styles_LineCap;
  /** Line thicknesses in pixels, ordered from first line to last line. */
  lineThickness: number[];
  /** Visible dash length for dashed dividers, in pixels. The pattern is snapped to a whole number of dashes so that the first and last dash touch the divider's edges - narrower containers show fewer dashes at the same size. */
  dashLength?: number;
  /** Visible gap between dashes or dots, in pixels. */
  dashGap?: number;
  /** Gap between divider lines in pixels. */
  lineGap?: number;
}

export function dividerData_Styles_LineCapFromJSON(
  object: any
): DividerData_Styles_LineCap {
  switch (object) {
    case 0:
    case "SQUARE":
      return DividerData_Styles_LineCap.SQUARE;
    case 1:
    case "ROUND":
      return DividerData_Styles_LineCap.ROUND;
    case -1:
    case "UNRECOGNIZED":
    default:
      return DividerData_Styles_LineCap.UNRECOGNIZED;
  }
}

export function dividerData_Styles_LineCapToJSON(
  object: DividerData_Styles_LineCap
): string {
  switch (object) {
    case DividerData_Styles_LineCap.SQUARE:
      return "SQUARE";
    case DividerData_Styles_LineCap.ROUND:
      return "ROUND";
    default:
      return "UNKNOWN";
  }
}

const baseDividerData: object = {
  lineStyle: DividerData_LineStyle.SINGLE,
  width: DividerData_Width.LARGE,
  alignment: DividerData_Alignment.CENTER,
};

export const DividerData = {
  fromJSON(object: any): DividerData {
    const message = { ...baseDividerData } as DividerData;
    message.containerData =
      object.containerData !== undefined && object.containerData !== null
        ? PluginContainerData.fromJSON(object.containerData)
        : undefined;
    message.lineStyle =
      object.lineStyle !== undefined && object.lineStyle !== null
        ? dividerData_LineStyleFromJSON(object.lineStyle)
        : DividerData_LineStyle.SINGLE;
    message.width =
      object.width !== undefined && object.width !== null
        ? dividerData_WidthFromJSON(object.width)
        : DividerData_Width.LARGE;
    message.alignment =
      object.alignment !== undefined && object.alignment !== null
        ? dividerData_AlignmentFromJSON(object.alignment)
        : DividerData_Alignment.CENTER;
    message.styles =
      object.styles !== undefined && object.styles !== null
        ? DividerData_Styles.fromJSON(object.styles)
        : undefined;
    message.animation =
      object.animation !== undefined && object.animation !== null
        ? Animation.fromJSON(object.animation)
        : undefined;
    return message;
  },

  toJSON(message: DividerData): unknown {
    const obj: any = {};
    message.containerData !== undefined &&
      (obj.containerData = message.containerData
        ? PluginContainerData.toJSON(message.containerData)
        : undefined);
    message.lineStyle !== undefined &&
      (obj.lineStyle = dividerData_LineStyleToJSON(message.lineStyle));
    message.width !== undefined &&
      (obj.width = dividerData_WidthToJSON(message.width));
    message.alignment !== undefined &&
      (obj.alignment = dividerData_AlignmentToJSON(message.alignment));
    message.styles !== undefined &&
      (obj.styles = message.styles
        ? DividerData_Styles.toJSON(message.styles)
        : undefined);
    message.animation !== undefined &&
      (obj.animation = message.animation
        ? Animation.toJSON(message.animation)
        : undefined);
    return obj;
  },
};

const baseDividerData_Styles: object = {
  lineCap: DividerData_Styles_LineCap.SQUARE,
  lineThickness: 0,
};

export const DividerData_Styles = {
  fromJSON(object: any): DividerData_Styles {
    const message = { ...baseDividerData_Styles } as DividerData_Styles;
    message.color =
      object.color !== undefined && object.color !== null
        ? String(object.color)
        : undefined;
    message.lineCap =
      object.lineCap !== undefined && object.lineCap !== null
        ? dividerData_Styles_LineCapFromJSON(object.lineCap)
        : DividerData_Styles_LineCap.SQUARE;
    message.lineThickness = (object.lineThickness ?? []).map((e: any) =>
      Number(e)
    );
    message.dashLength =
      object.dashLength !== undefined && object.dashLength !== null
        ? Number(object.dashLength)
        : undefined;
    message.dashGap =
      object.dashGap !== undefined && object.dashGap !== null
        ? Number(object.dashGap)
        : undefined;
    message.lineGap =
      object.lineGap !== undefined && object.lineGap !== null
        ? Number(object.lineGap)
        : undefined;
    return message;
  },

  toJSON(message: DividerData_Styles): unknown {
    const obj: any = {};
    message.color !== undefined && (obj.color = message.color);
    message.lineCap !== undefined &&
      (obj.lineCap = dividerData_Styles_LineCapToJSON(message.lineCap));
    if (message.lineThickness) {
      obj.lineThickness = message.lineThickness.map((e) => Math.round(e));
    } else {
      obj.lineThickness = [];
    }
    message.dashLength !== undefined && (obj.dashLength = message.dashLength);
    message.dashGap !== undefined && (obj.dashGap = message.dashGap);
    message.lineGap !== undefined && (obj.lineGap = message.lineGap);
    return obj;
  },
};
