/* eslint-disable */
import { PluginContainerData, FileSource } from './common.js';
import { Animation } from './animation.js';

import { FileData_PDFSettings_ViewMode } from './plugin_file.enums.js';

export interface FileData {
  /** Styling for the file's container. */
  containerData?: PluginContainerData;
  /** The source for the file's data. */
  src?: FileSource;
  /** File name. */
  name?: string;
  /** File type. */
  type?: string;
  /**
   * Use `sizeInKb` instead.
   *
   * @deprecated
   */
  size?: number;
  /** Settings for PDF files. */
  pdfSettings?: FileData_PDFSettings;
  /** File MIME type. */
  mimeType?: string;
  /** File path. */
  path?: string;
  /** File size in KB. */
  sizeInKb?: string;
  /** Node animation. */
  animation?: Animation;
}

export interface FileData_PDFSettings {
  /**
   * PDF view mode. One of the following:
   * `NONE` : The PDF isn't displayed.
   * `FULL` : A full page view of the PDF is displayed.
   * `MINI` : A mini view of the PDF is displayed.
   */
  viewMode: FileData_PDFSettings_ViewMode;
  /** Sets whether the PDF download button is disabled. Defaults to `false`. */
  disableDownload?: boolean;
  /** Sets whether the PDF print button is disabled. Defaults to `false`. */
  disablePrint?: boolean;
}

export function fileData_PDFSettings_ViewModeFromJSON(
  object: any
): FileData_PDFSettings_ViewMode {
  switch (object) {
    case 0:
    case "NONE":
      return FileData_PDFSettings_ViewMode.NONE;
    case 1:
    case "FULL":
      return FileData_PDFSettings_ViewMode.FULL;
    case 2:
    case "MINI":
      return FileData_PDFSettings_ViewMode.MINI;
    case -1:
    case "UNRECOGNIZED":
    default:
      return FileData_PDFSettings_ViewMode.UNRECOGNIZED;
  }
}

export function fileData_PDFSettings_ViewModeToJSON(
  object: FileData_PDFSettings_ViewMode
): string {
  switch (object) {
    case FileData_PDFSettings_ViewMode.NONE:
      return "NONE";
    case FileData_PDFSettings_ViewMode.FULL:
      return "FULL";
    case FileData_PDFSettings_ViewMode.MINI:
      return "MINI";
    default:
      return "UNKNOWN";
  }
}

const baseFileData: object = {};

export const FileData = {
  fromJSON(object: any): FileData {
    const message = { ...baseFileData } as FileData;
    message.containerData =
      object.containerData !== undefined && object.containerData !== null
        ? PluginContainerData.fromJSON(object.containerData)
        : undefined;
    message.src =
      object.src !== undefined && object.src !== null
        ? FileSource.fromJSON(object.src)
        : undefined;
    message.name =
      object.name !== undefined && object.name !== null
        ? String(object.name)
        : undefined;
    message.type =
      object.type !== undefined && object.type !== null
        ? String(object.type)
        : undefined;
    message.size =
      object.size !== undefined && object.size !== null
        ? Number(object.size)
        : undefined;
    message.pdfSettings =
      object.pdfSettings !== undefined && object.pdfSettings !== null
        ? FileData_PDFSettings.fromJSON(object.pdfSettings)
        : undefined;
    message.mimeType =
      object.mimeType !== undefined && object.mimeType !== null
        ? String(object.mimeType)
        : undefined;
    message.path =
      object.path !== undefined && object.path !== null
        ? String(object.path)
        : undefined;
    message.sizeInKb =
      object.sizeInKb !== undefined && object.sizeInKb !== null
        ? String(object.sizeInKb)
        : undefined;
    message.animation =
      object.animation !== undefined && object.animation !== null
        ? Animation.fromJSON(object.animation)
        : undefined;
    return message;
  },

  toJSON(message: FileData): unknown {
    const obj: any = {};
    message.containerData !== undefined &&
      (obj.containerData = message.containerData
        ? PluginContainerData.toJSON(message.containerData)
        : undefined);
    message.src !== undefined &&
      (obj.src = message.src ? FileSource.toJSON(message.src) : undefined);
    message.name !== undefined && (obj.name = message.name);
    message.type !== undefined && (obj.type = message.type);
    message.size !== undefined && (obj.size = message.size);
    message.pdfSettings !== undefined &&
      (obj.pdfSettings = message.pdfSettings
        ? FileData_PDFSettings.toJSON(message.pdfSettings)
        : undefined);
    message.mimeType !== undefined && (obj.mimeType = message.mimeType);
    message.path !== undefined && (obj.path = message.path);
    message.sizeInKb !== undefined && (obj.sizeInKb = message.sizeInKb);
    message.animation !== undefined &&
      (obj.animation = message.animation
        ? Animation.toJSON(message.animation)
        : undefined);
    return obj;
  },
};

const baseFileData_PDFSettings: object = {
  viewMode: FileData_PDFSettings_ViewMode.NONE,
};

export const FileData_PDFSettings = {
  fromJSON(object: any): FileData_PDFSettings {
    const message = { ...baseFileData_PDFSettings } as FileData_PDFSettings;
    message.viewMode =
      object.viewMode !== undefined && object.viewMode !== null
        ? fileData_PDFSettings_ViewModeFromJSON(object.viewMode)
        : FileData_PDFSettings_ViewMode.NONE;
    message.disableDownload =
      object.disableDownload !== undefined && object.disableDownload !== null
        ? Boolean(object.disableDownload)
        : undefined;
    message.disablePrint =
      object.disablePrint !== undefined && object.disablePrint !== null
        ? Boolean(object.disablePrint)
        : undefined;
    return message;
  },

  toJSON(message: FileData_PDFSettings): unknown {
    const obj: any = {};
    message.viewMode !== undefined &&
      (obj.viewMode = fileData_PDFSettings_ViewModeToJSON(message.viewMode));
    message.disableDownload !== undefined &&
      (obj.disableDownload = message.disableDownload);
    message.disablePrint !== undefined &&
      (obj.disablePrint = message.disablePrint);
    return obj;
  },
};
